// 將各來源的 conversation 數組扁平化，並補充來源與時間戳
const allData = items.map(item => item.json);
// 假設各來源均返回 { conversations: [ { id, content, timestamp, source } ] }
let conversations = [];
allData.forEach(sourceData => {
  if (sourceData.conversations && Array.isArray(sourceData.conversations)) {
    conversations = conversations.concat(sourceData.conversations);
  }
});
// 如有需要，可在此處為每條記錄補充來源信息
const processed = conversations.map(conv => ({
  id: conv.id || Date.now().toString(),
  content: conv.content,
  source: conv.source || 'unknown',
  timestamp: conv.timestamp || new Date().toISOString()
}));
return processed.map(conv => ({ json: conv }));

