// Import required libraries
const puppeteer = require('puppeteer-extra');
const StealthPlugin = require('puppeteer-extra-plugin-stealth');
const { executablePath } = require('puppeteer');
const path = require('path');
const fs = require('fs');
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

// Use Stealth plugin to avoid detection
puppeteer.use(StealthPlugin());

// Main registration function
async function registerInstagram(account, proxyUrl, twoCaptchaApiKey) {
  console.log(`Starting registration for ${account.username}...`);

  // 2Captcha extension path configuration
  const pathToExtension = path.join(__dirname, '2captcha-solver');

  // Ensure extension directory exists
  if (!fs.existsSync(pathToExtension)) {
    fs.mkdirSync(pathToExtension, { recursive: true });

    // Configure 2captcha-solver extension
    const configPath = path.join(pathToExtension, 'common/config.js');
    if (fs.existsSync(configPath)) {
      let configContent = fs.readFileSync(configPath, 'utf8');
      configContent = configContent.replace(/apiKey: ""/g, `apiKey: "${twoCaptchaApiKey}"`);
      configContent = configContent.replace(/autoSolveRecaptchaV2: false/g, 'autoSolveRecaptchaV2: true');
      fs.writeFileSync(configPath, configContent);
    }
  }

  // Browser launch options
  const launchOptions = {
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-infobars',
      '--window-size=1280,800',
      '--disable-blink-features=AutomationControlled',
      `--disable-extensions-except=${pathToExtension}`,
      `--load-extension=${pathToExtension}`
    ],
    executablePath: executablePath()
  };

  // Set proxy if provided
  if (proxyUrl) {
    launchOptions.args.push(`--proxy-server=${proxyUrl}`);
  }

  const browser = await puppeteer.launch(launchOptions);
  const page = await browser.newPage();

  // Set realistic user agent
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36');

  // Handle proxy authentication
  if (proxyUrl && proxyUrl.includes('@')) {
    const proxyAuth = proxyUrl.split('@')[0].split('//')[1];
    const [username, password] = proxyAuth.split(':');
    await page.authenticate({ username, password });
  }

  try {
    // Visit Instagram signup page
    console.log('Visiting Instagram signup page...');
    await page.goto('https://www.instagram.com/accounts/emailsignup/', { 
      waitUntil: 'networkidle2',
      timeout: 60000 
    });

    // Random delay
    await delay(Math.floor(Math.random() * 2000) + 3000);

    // Handle cookie consent popup
    const cookieButtons = await page.$x('//button[contains(text(), "Allow") or contains(text(), "Accept") or contains(text(), "允許") or contains(text(), "接受")]');
    if (cookieButtons.length > 0) {
      await cookieButtons[0].click();
      await delay(Math.floor(Math.random() * 1000) + 1000);
    }

    // Input email
    console.log('Entering email address...');
    await page.type('input[name="emailOrPhone"]', account.email, { delay: Math.floor(Math.random() * 50) + 70 });
    await delay(Math.floor(Math.random() * 1000) + 1000);

    // Input full name
    console.log('Entering full name...');
    await page.type('input[name="fullName"]', account.fullName, { delay: Math.floor(Math.random() * 50) + 70 });
    await delay(Math.floor(Math.random() * 1000) + 1000);

    // Input username
    console.log('Entering username...');
    await page.type('input[name="username"]', account.username, { delay: Math.floor(Math.random() * 50) + 70 });
    await delay(Math.floor(Math.random() * 1000) + 1000);

    // Input password
    console.log('Entering password...');
    await page.type('input[name="password"]', account.password, { delay: Math.floor(Math.random() * 50) + 70 });
    await delay(Math.floor(Math.random() * 1000) + 1000);

    // Click signup button
    console.log('Clicking signup button...');
    const signupButtons = await page.$x('//button[contains(text(), "註冊") or contains(text(), "Sign up")]');
    if (signupButtons.length > 0) {
      // Add mouse movement to simulate human behavior
      const button = signupButtons[0];
      const buttonBox = await button.boundingBox();

      // Move to button vicinity, then to button
      await page.mouse.move(
        buttonBox.x + Math.random() * buttonBox.width,
        buttonBox.y - 10 + Math.random() * 10
      );
      await delay(Math.floor(Math.random() * 500) + 300);
      await page.mouse.move(
        buttonBox.x + buttonBox.width / 2,
        buttonBox.y + buttonBox.height / 2
      );
      await delay(Math.floor(Math.random() * 500) + 300);

      // Click the button
      await button.click();
      console.log('Signup button clicked');
    } else {
      throw new Error('Signup button not found');
    }

    // Wait for next phase of registration
    await delay(Math.floor(Math.random() * 2000) + 4000);

    // Handle birthday selection page
    console.log('Checking if birthday selection is required...');
    const birthdayForm = await page.$('select[title="月:"], select[aria-label*="Month"]');
    if (birthdayForm) {
      console.log('Handling birthday selection...');

      // Select month
      await page.select('select[title="月:"], select[aria-label*="Month"]', account.birthMonth);
      await delay(Math.floor(Math.random() * 1000) + 1000);

      // Select day
      await page.select('select[title="日:"], select[aria-label*="Day"]', account.birthDay);
      await delay(Math.floor(Math.random() * 1000) + 1000);

      // Select year
      await page.select('select[title="年:"], select[aria-label*="Year"]', account.birthYear);
      await delay(Math.floor(Math.random() * 1000) + 1000);

      // Click next button
      const nextButtons = await page.$x('//button[contains(text(), "下一步") or contains(text(), "Next")]');
      if (nextButtons.length > 0) {
        await nextButtons[0].click();
        console.log('Next button clicked');
      }
      await delay(Math.floor(Math.random() * 2000) + 3000);
    }

    // Handle captcha challenge
    console.log('Checking and handling captcha challenges...');

    // Wait for 2captcha extension to load
    await delay(5000);

    // Check if captcha element exists
    const captchaFrame = await page.$('iframe[src*="captcha"]');
    if (captchaFrame) {
      console.log('Captcha challenge detected, using 2Captcha to solve...');

      // Wait for 2Captcha extension to auto-process captcha
      // Check for .captcha-solver element
      await page.waitForSelector('.captcha-solver', { timeout: 10000 }).catch(() => {});

      // If element exists but hasn't auto-started solving, click it
      const captchaSolverState = await page.evaluate(() => {
        const solver = document.querySelector('.captcha-solver');
        return solver ? solver.getAttribute('data-state') : null;
      }).catch(() => null);

      if (captchaSolverState && captchaSolverState !== 'solving') {
        await page.click('.captcha-solver').catch(() => {});
        console.log('Clicked 2Captcha solver button');
      }

      // Wait for captcha to be solved
      console.log('Waiting for captcha to be solved...');
      await page.waitForSelector('.captcha-solver[data-state="solved"]', { timeout: 180000 }).catch(() => {});
      console.log('Captcha solved');

      // Continue registration flow
      await delay(2000);

      // Click submit button (if any)
      const submitButtons = await page.$x('//button[contains(text(), "提交") or contains(text(), "Submit")]').catch(() => []);
      if (submitButtons.length > 0) {
        await submitButtons[0].click().catch(() => {});
        console.log('Submit button clicked');
      }
    }

    // Wait for registration to complete
    await delay(10000);

    // Check if email verification is required
    const emailVerificationText = await page.evaluate(() => {
      const elements = Array.from(document.querySelectorAll('*'));
      return elements.find(el => el.textContent.includes('驗證您的電子郵件') || 
                              el.textContent.includes('Verify your email') || 
                              el.textContent.includes('確認您的電子郵件地址'))?.textContent || '';
    }).catch(() => '');

    let registrationResult = {
      success: true,
      message: 'Registration successful',
      account: account
    };

    if (emailVerificationText) {
      registrationResult.message += ', email verification required';
      registrationResult.requiresEmailVerification = true;
    }

    // Check for error messages
    const errorText = await page.evaluate(() => {
      const elements = Array.from(document.querySelectorAll('*'));
      return elements.find(el => el.textContent.includes('錯誤') || 
                              el.textContent.includes('Error') || 
                              el.textContent.includes('請稍後再試'))?.textContent || '';
    }).catch(() => '');

    if (errorText) {
      registrationResult.success = false;
      registrationResult.message = `Registration failed: ${errorText}`;
    }

    // Check for feedback required error
    const feedbackRequired = await page.evaluate(() => {
      return document.body.innerText.includes('feedback_required') || 
             document.body.innerText.includes('Feedback Required') ||
             document.body.innerText.includes('請稍後再試');
    }).catch(() => false);

    if (feedbackRequired) {
      registrationResult.success = false;
      registrationResult.message = 'Registration failed: Feedback Required error, possible automation detection';
    }

    // Take screenshot as evidence
    const screenshotPath = `/tmp/${account.username}_${Date.now()}.png`;
    await page.screenshot({ path: screenshotPath, fullPage: true }).catch(() => {});
    registrationResult.screenshotPath = screenshotPath;

    return registrationResult;

  } catch (error) {
    console.error('Error during registration process:', error);
    return {
      success: false,
      message: `Registration failed: ${error.message}`,
      account: account
    };
  } finally {
    // Close browser
    await browser.close().catch(() => {});
  }
}

// Execute function and return result
return await registerInstagram($input.item.json.account, $input.item.json.proxy, $input.item.json.twoCaptchaApiKey);

