const proxyList = $json['Configure Registration Data1'].json.proxyList;

// Use username to deterministically select a proxy (same account = same proxy)
const username = $input.item.json.username;
const charSum = [...username].reduce((sum, char) => sum + char.charCodeAt(0), 0);
const proxyIndex = charSum % proxyList.length;

$input.item.json.proxy = proxyList[proxyIndex];
$input.item.json.account = $input.item.json;
$input.item.json.twoCaptchaApiKey = $json['Configure Registration Data1'].json.twoCaptchaApiKey;

return $input.item;

// Add proxy to each item
// First, get the proxy list from a global variable
let proxyList = [];
try {
  // Try to get from the workflow data
  proxyList = $workflow.variables.proxyList || ["http://default:default@proxy.example.com:8080"];
} catch (e) {
  // Fallback to a default proxy
  proxyList = ["http://default:default@proxy.example.com:8080"];
}

// Use username to deterministically select a proxy
const username = $input.item.json.username;
const charSum = [...username].reduce((sum, char) => sum + char.charCodeAt(0), 0);
const proxyIndex = charSum % proxyList.length;

// Add needed data to the item
$input.item.json.proxy = proxyList[proxyIndex];
$input.item.json.account = $input.item.json;

// Set a default 2Captcha API key if not available from workflow variables
try {
  $input.item.json.twoCaptchaApiKey = $workflow.variables.twoCaptchaApiKey || "YOUR_DEFAULT_2CAPTCHA_KEY";
} catch (e) {
  $input.item.json.twoCaptchaApiKey = "YOUR_DEFAULT_2CAPTCHA_KEY";
}

return $input.item;

